void AudioLoopbackPrivate::CapturerCallbackImpl::OnStateChange(const AudioDeviceDescriptor &deviceInfo)
{
    AUDIO_INFO_LOG("CapturerCallback device change to %{public}d", deviceInfo.deviceType_);
    std::vector<std::shared_ptr<AudioDeviceDescriptor>> inputDevices =
        AudioPolicyManager::GetInstance().GetPreferredInputDeviceDescriptors(capturerOptions_.capturerInfo);
    parent_.isCapturerUsb_ = (!inputDevices.empty() && inputDevices[0] != nullptr) &&
        parent_.activeInputDevice_ == inputDevices[0]->deviceType_;
    parent_.UpdateStatus();
}

void AudioLoopbackPrivate::CapturerCallbackImpl::OnStateChange(const AudioDeviceDescriptor &deviceInfo)
{
    AUDIO_INFO_LOG("CapturerCallback device change to %{public}d", deviceInfo.deviceType_);
    std::vector<std::shared_ptr<AudioDeviceDescriptor>> inputDevices =
        AudioPolicyManager::GetInstance().GetPreferredInputDeviceDescriptors(capturerOptions_.capturerInfo);
    parent_.isCapturerUsb_ = (!inputDevices.empty() && inputDevices[0] != nullptr) &&
        parent_.activeInputDevice_ == inputDevices[0]->deviceType_;
    parent_.UpdateStatus();
}

HWTEST_F(AudioLoopbackUnitTest, Audio_Loopback_CheckDeviceSupport_001, TestSize.Level1)
{
    auto audioLoopback = std::make_shared<AudioLoopbackPrivate>(LOOPBACK_HARDWARE, AppInfo());
    audioLoopback->validDevice.clear();
    int32_t ret = audioLoopback->CheckDeviceSupport();
    if (ret == DEFAULT_OK) {
        EXPECT_EQ(audioLoopback->isRendererUsb_, true);
        EXPECT_EQ(audioLoopback->isCapturerUsb_, true);
        EXPECT_NE(audioLoopback->activeOutputDevice_, DEVICE_TYPE_NONE);
        EXPECT_NE(audioLoopback->activeInputDevice_, DEVICE_TYPE_NONE);
    } else {
        EXPECT_EQ(ret, ERROR_DEVICE_NOT_SUPPORT);
        EXPECT_EQ(audioLoopback->isRendererUsb_, false);
        EXPECT_EQ(audioLoopback->isCapturerUsb_, false);
    }
}
